use super::prelude::*;

/// Ashwater — exhaust any number of chosen hand cards (player choice).
/// See the body for the C# mapping and the `sts2-rs-1xmxp` rebody from
/// the prior uniform-random subset. Empty hand → no-op (mirrors Python
/// `if not combat.hand: return`). The `ExhaustFromHand` resolver routes
/// per-card through [`sts2_core::card_effects::exhaust_card_uid`] so the
/// `on_card_exhausted` listener bus fires once per card. Beads
/// `sts2-rs-bavw` (original) / `sts2-rs-1xmxp` (player-choice rebody).
pub(crate) fn drink_ashwater(state: &mut CombatState, _target: Option<u8>) -> EffectResult {
    if state.player.hand.is_empty() {
        return EffectResult::Resolved;
    }
    // C# Ashwater = `CardSelectCmd.FromHand(prefs(0, 999999999))` →
    // exhaust each selected: a player choice to exhaust ANY number of
    // hand cards (consuming no RunRngSet stream). Bead `sts2-rs-1xmxp`
    // replaces the prior uniform-random subset (the `NOTE(sts2-rs-sr3ql)`
    // legacy-rng caveat is now resolved). Open an `ExhaustFromHand`
    // choice over the whole hand (min 0, max = hand size, skippable); the
    // `sts2-rs-enwwr` fan-out enumerates the selections and the resolver
    // exhausts each chosen card.
    let options: Vec<sts2_core::ChoiceOption> = state
        .player
        .hand
        .iter()
        .map(|&uid| {
            let idx = uid.0.get() as usize - 1;
            sts2_core::ChoiceOption {
                card_id: state.cards[idx].card_id,
                upgraded: state.cards[idx].upgraded,
                card_uid: Some(uid),
                source_pile: Some(sts2_core::cards::PileKind::Hand),
            }
        })
        .collect();
    let max = u8::try_from(options.len()).unwrap_or(u8::MAX);
    state.request_card_choice(
        sts2_core::ChoiceKind::ExhaustFromHand,
        options,
        0,
        max,
        true,
    );
    EffectResult::Resolved
}
